MATCH (a:PlantItem {tag: 'P-1801'}), (b:PlantItem {tag: 'V-1501'})
CALL {
  WITH a
  MATCH (a)-[:line_to*1..]->(x:PlantItem)
  RETURN collect(DISTINCT x) AS downstreamA
}
CALL {
  WITH b
  MATCH (b)-[:line_to*1..]->(y:PlantItem)
  RETURN collect(DISTINCT y) AS downstreamB
}
WITH [x IN downstreamA WHERE x IN downstreamB] AS common
UNWIND common AS c
WHERE NOT EXISTS {
  UNWIND common AS d
  WITH c, d
  WHERE d <> c
    AND EXISTS { (d)-[:line_to*1..]->(c) }
}
RETURN DISTINCT c.tag AS tag
ORDER BY tag

